const d=msg.payload; const cards=d.cards||[];
const ny=cards.filter(c=>(c.requests||[]).some(r=>r.status!=='answered')).length;
const rev=cards.filter(c=>(c.column||'backlog')==='review').length;
const doing=cards.filter(c=>(c.column||'backlog')==='doing').length;
msg.fact={name:'kanban', ok:true, line:`${cards.length} cards · ${ny} needs-you · ${rev} review · ${doing} doing`, ny, rev, doing};
return msg;

const f=msg.fact; const stash=flow.get('facts')||{}; stash[f.name]=f; flow.set('facts',stash);
const facts=Object.values(stash);
const ts=new Date().toISOString().slice(0,19).replace('T',' ');
const bad=facts.filter(x=>!x.ok).map(x=>x.name).join(', ')||'none';
let md='# Node-RED live report — demo

';
md+=`_Auto-refreshed every 5 min by Node-RED on tony-dell. fresh_for=15m — if the index flags STALE, Node-RED is dead._

`;
md+='## Specialist blocks

';
for(const x of facts){ md+=`- **${x.name}**: ${x.line}
`; }
md+='
## Heartbeat

';
md+=`ts=${ts}Z · host=tony-dell · flow=cms-live-report demo
`;
md+='
## How to extend

';
md+='Clone a source node + a `specialist:` function, wire into `compose report`. Each specialist contributes one `msg.fact={name, ok, line}` — the Chaba Nest pattern: small per-domain producers, one aggregate live report.
';
msg.payload=JSON.stringify({collection:'ada-cms-pages',key:'nodred-live-demo',lang:'en',contentMd:md,meta:{kind:['report'],slug:['nodred-live-demo'],title:['Node-RED live report — demo'],format:['markdown'],lang:['en'],written_by:['node-red'],source:['node-red'],domain:['ops'],fresh_for:['15m'],confidence:['high'],subject:['nodred-live-demo'],attribute:['page'],bank:['cms'],scope:['tony'],status:['active'],instance:['ada'],summary:[`Node-RED live ops demo — ${facts.length} specialists reporting, unhealthy: ${bad}`],updated:[new Date().toISOString()]}});
msg.headers={'Content-Type':'application/json'};
return msg;

const ss=Array.isArray(msg.payload)?msg.payload:[];
const by=function(id){const s=ss.find(function(x){return x.entity_id===id});return s?s.state:null};
const tony=by("person.tony")||"?";
const cpu=by("sensor.tony_omen_cpu_package_temp"), gpu=by("sensor.tony_omen_gpu_temp");
const sun=by("sun.sun")||"?";
const temps=[cpu,gpu].map(Number).filter(function(t){return !isNaN(t)});
const hot=temps.some(function(t){return t>85}), warm=temps.some(function(t){return t>75});
const tail=hot?" ⚠HOT":(warm?" (warm)":"");
msg.fact={name:"house-pulse",ok:!hot,
 line:"tony "+tony+" · sun "+sun+" · omen cpu "+(cpu||"?")+"°C gpu "+(gpu||"?")+"°C"+tail};
return msg;

try{const d=JSON.parse(msg.payload);
const n=d.stale_count||0;const us=(d.stale_units||[]).join(", ");
msg.fact={name:"ops-health",ok:n===0,
 line:n===0?"all services fresh ("+d.host+")":(n+" stale: "+us+" ⚠")};
}catch(e){msg.fact={name:"ops-health",ok:false,line:"sentinel status unreadable"}}
return msg;

const code=msg.statusCode;
msg.fact={name:"web-edge",ok:code===200,
 line:code===200?"caddy + board2 200":"board2 returned "+code+" ⚠"};
return msg;
